MANAGED_DIRS = {
    "mods": True, "resourcepacks": True, "datapacks": True, "config": False,
}

BG_B64 = ""

def sha1_of_file(path):
    h = hashlib.sha1()
    with open(path,"rb") as f:
        for chunk in iter(lambda: f.read(65536), b""):
            h.update(chunk)
    return h.hexdigest()

def fetch_json(url):
    req = urllib.request.Request(url, headers={"User-Agent":"CobblemonLauncher/1.2"})
    with urllib.request.urlopen(req, timeout=15) as r:
        return json.loads(r.read().decode())

def download_file(url, dest, cb=None):
    req = urllib.request.Request(url, headers={"User-Agent":"CobblemonLauncher/1.2"})
    with urllib.request.urlopen(req, timeout=60) as r:
        total = int(r.headers.get("Content-Length",0))
        done = 0
        dest.parent.mkdir(parents=True, exist_ok=True)
        with open(dest,"wb") as f:
            while True:
                chunk = r.read(65536)
                if not chunk: break
                f.write(chunk)
                done += len(chunk)
                if cb and total: cb(done/total)

def load_meta():
    if META_FILE.exists():
        with open(META_FILE,"r",encoding="utf-8") as f:
            return json.load(f)
    return {"version": None}

def save_meta(meta):
    META_FILE.parent.mkdir(parents=True, exist_ok=True)
    with open(META_FILE,"w",encoding="utf-8") as f:
        json.dump(meta, f, ensure_ascii=False, indent=2)

def parse_mrpack(p):
    with zipfile.ZipFile(p,"r") as z:
        with z.open("modrinth.index.json") as f:
            return json.load(f)

def sync_mods(mrpack_path, log_cb, prog_cb):
    index = parse_mrpack(mrpack_path)
    remote = {Path(e["path"]).name: e for e in index["files"] if e["path"].startswith("mods/")}
    MODS_DIR.mkdir(parents=True, exist_ok=True)
    local = {p.name for p in MODS_DIR.glob("*.jar")}
    for name in local - set(remote.keys()):
        (MODS_DIR/name).unlink()
        log_cb(f"[삭제] {name}")
    to_dl = [(n,i) for n,i in remote.items()
              if not (MODS_DIR/n).exists() or sha1_of_file(MODS_DIR/n)!=i["hashes"]["sha1"]]
    if not to_dl:
        log_cb("모드: 모두 최신 상태")
        prog_cb(1.0); return
    log_cb(f"모드: {len(to_dl)}개 업데이트")
    for i,(name,info) in enumerate(to_dl):
        log_cb(f"[{i+1}/{len(to_dl)}] {name}")
        download_file(info["downloads"][0], MODS_DIR/name)
        prog_cb((i+1)/len(to_dl))

def sync_overrides(mrpack_path, log_cb):
    with zipfile.ZipFile(mrpack_path,"r") as z:
        entries = [n for n in z.namelist() if n.startswith("overrides/")]
        if not entries: return
        remote_by = {}
        for e in entries:
            rel = e[len("overrides/"):]
            if not rel or e.endswith("/"): continue
            folder = Path(rel).parts[0]
            remote_by.setdefault(folder,set()).add(Path(rel).name)
        for folder, managed in MANAGED_DIRS.items():
            if not managed: continue
            ld = INSTANCE_DIR/folder
            if not ld.exists(): continue
            for lf in ld.iterdir():
                if lf.is_file() and lf.name not in remote_by.get(folder,set()):
                    lf.unlink(); log_cb(f"[삭제] {folder}/{lf.name}")
        changed = []
        for e in entries:
            rel = e[len("overrides/"):]
            if not rel or e.endswith("/"): continue
            dest = INSTANCE_DIR/rel
            dest.parent.mkdir(parents=True, exist_ok=True)
            with z.open(e) as src:
                data = src.read()
            if dest.exists() and dest.read_bytes()==data: continue
            dest.write_bytes(data); changed.append(rel)
        if changed: log_cb(f"설정/리소스: {len(changed)}개 업데이트")
        else: log_cb("설정/리소스: 모두 최신 상태")

def find_modrinth():
    for p in [
        Path(os.environ.get("LOCALAPPDATA",""))/"ModrinthApp"/"ModrinthApp.exe",
        Path(os.environ.get("LOCALAPPDATA",""))/"Programs"/"ModrinthApp"/"ModrinthApp.exe",
    ]:
        if p.exists(): return p
    return None

