class Api:
    def __init__(self, window_ref):
        self._win = window_ref

    def _js(self, code):
        try: self._win.evaluate_js(code)
        except: pass

    def _log(self, msg, cls="info"):
        safe = msg.replace("\\","\\\\").replace("'","\\'")
        self._js(f"log('{safe}','{cls}')")

    def _prog(self, v):
        self._js(f"setProgress({v})")

    def init_check(self):
        meta = load_meta()
        lv = meta.get("version") or "미설치"
        self._js(f"setLocalVer('{lv}')")
        def task():
            try:
                remote = fetch_json(VERSION_URL)
                rv = remote.get("version","?")
                same = lv == rv
                self._js(f"setRemoteVer('{rv}',{str(same).lower()})")
                if same:
                    self._log("최신 버전이 설치되어 있습니다.", "ok")
                    self._js("setBtn('✓ 최신 버전',false)")
                else:
                    self._log(f"업데이트 가능: {lv} → {rv}", "info")
                    self._js("setBtn('▼ 업데이트',false)")
            except Exception as e:
                self._log(f"버전 확인 실패: {e}", "err")
                self._js("setRemoteVer('연결 실패',false)")
        threading.Thread(target=task, daemon=True).start()

    def do_update(self):
        self._js("setBtn('업데이트 중...',true)")
        def task():
            try:
                self._log("버전 정보 확인 중...")
                self._prog(0)
                remote = fetch_json(VERSION_URL)
                rv = remote["version"]
                url = remote["mrpack_url"]
                tmp = Path(tempfile.gettempdir()) / "cobblemon_update.mrpack"
                self._log(f"모드팩 다운로드 중 (v{rv})...")
                download_file(url, tmp, lambda p: self._prog(p*0.25))
                self._log("모드 동기화 중...")
                sync_mods(tmp, self._log, lambda p: self._prog(0.25+p*0.65))
                self._log("설정/리소스 동기화 중...")
                sync_overrides(tmp, self._log)
                self._prog(1.0)
                save_meta({"version": rv})
                self._js(f"setLocalVer('{rv}')")
                self._js(f"setRemoteVer('{rv}',true)")
                self._log("업데이트 완료!", "ok")
                self._js("setBtn('✓ 최신 버전',false)")
                tmp.unlink(missing_ok=True)
            except Exception as e:
                self._log(f"오류: {e}", "err")
                self._js("setBtn('▼ 업데이트',false)")
        threading.Thread(target=task, daemon=True).start()

    def open_modrinth(self):
        m = find_modrinth()
        if m:
            subprocess.Popen([str(m)])
        else:
            self._log("Modrinth 앱을 찾을 수 없습니다.", "err")

def main():
    try:
        import webview
    except ImportError:
        print("pywebview가 설치되지 않았습니다.")
        print("아래 명령어를 실행해주세요:")
        print("  pip install pywebview")
        input("Enter를 누르면 종료...")
        return

    bg_b64 = BG_B64
    html = HTML_TEMPLATE.replace("BG_BASE64", bg_b64)

    window = webview.create_window(
        "Cobblemon Self-Made Launcher",
        html=html,
        width=900, height=520,
        resizable=False,
        frameless=False,
    )
    api = Api(window)
    window.expose(api.init_check, api.do_update, api.open_modrinth)
    webview.start(debug=False)

if __name__ == "__main__":
    main()
